from collections import deque
def transform(g):
    H,W=len(g),len(g[0])
    o=[row[:] for row in g]
    def is_red(r,c): return o[r][c]==2
    def is8(r,c): return 0<=r<H and 0<=c<W and g[r][c]==8
    def gapcell(r,c):
        # 0-cell flanked by 8s vertically or horizontally (a gap in a wall)
        if not(0<=r<H and 0<=c<W) or g[r][c]!=0: return False
        return (is8(r-1,c) and is8(r+1,c)) or (is8(r,c-1) and is8(r,c+1))
    def start(r,c,d):
        q=deque([(r,c,d)])
        while q:
            r,c,d=q.popleft()
            while True:
                if is_red(r,c) and (r,c)!=(o and (0,0)) and not (r,c)==startpos: break
                # side gaps
                perp=[(0,1),(0,-1)] if d in ((1,0),(-1,0)) else [(1,0),(-1,0)]
                spawned=False
                for dr,dc in perp:
                    s=(r+dr,c+dc)
                    if gapcell(*s):
                        q.append((s[0],s[1],(dr,dc))); spawned=True
                if spawned: break
                nr,nc=r+d[0],c+d[1]
                if not(0<=nr<H and 0<=nc<W): break
                if g[nr][nc]==8:
                    for dr,dc in perp:
                        q.append((r,c,(dr,dc)))
                    break
                if is_red(nr,nc): break
